import{_ as p,a0 as l,w as d,s as r,ao as o,I as i,x as a,a1 as e,A as t}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"在 Linux 上为你的任务创建一个自定义的系统托盘指示器 | LCTT x X-CMD","titleTemplate":false,"description":"在 Linux 上为你的任务创建一个自定义的系统托盘指示器 | LCTT (201907) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Linux 上为你的任务创建一个自定义的系统托盘指示器 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Linux 上为你的任务创建一个自定义的系统托盘指示器 | LCTT (201907) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201907/20190302 Create a Custom System Tray Indicator For Your Tasks on Linux","title":"在 Linux 上为你的任务创建一个自定义的系统托盘指示器","tag":"201907","desc":""},"relativePath":"201907/20190302 Create a Custom System Tray Indicator For Your Tasks on Linux.md","filePath":"[post].md"}'),c={name:"201907/20190302 Create a Custom System Tray Indicator For Your Tasks on Linux.md"};function u(m,s,h,g,k,y){const n=l("Link");return d(),r("div",null,[s[18]||(s[18]=o('<h1 id="在-linux-上为你的任务创建一个自定义的系统托盘指示器" tabindex="-1">在 Linux 上为你的任务创建一个自定义的系统托盘指示器 <a class="header-anchor" href="#在-linux-上为你的任务创建一个自定义的系统托盘指示器" aria-label="Permalink to “在 Linux 上为你的任务创建一个自定义的系统托盘指示器”">​</a></h1><p>系统托盘图标如今仍是一个很神奇的功能。只需要右击图标，然后选择想要的动作，你就可以大幅简化你的生活并且减少日常行为中的大量无用的点击。</p><p>一说到有用的系统托盘图标，我们很容易就想到 Skype、Dropbox 和 VLC：</p><p><img src="https://i2.wp.com/fosspost.org/wp-content/uploads/2019/02/Screenshot-at-2019-02-28-0808.png?resize=407%2C345&amp;ssl=1" alt="Create a Custom System Tray Indicator For Your Tasks on Linux" title="Create a Custom System Tray Indicator For Your Tasks on Linux 12"></p><p>然而系统托盘图标实际上要更有用得多；你可以根据自己的需求创建自己的系统托盘图标。本指导将会教你通过简单的几个步骤来实现这一目的。</p><h3 id="前置条件" tabindex="-1">前置条件 <a class="header-anchor" href="#前置条件" aria-label="Permalink to “前置条件”">​</a></h3><p>我们将要用 Python 来实现一个自定义的系统托盘指示器。Python 可能已经默安装在所有主流的 Linux 发行版中了，因此你只需要确定一下它已经被安装好了（此处使用版本为 2.7）。另外，我们还需要安装好 <code>gir1.2-appindicator3</code> 包。该库能够让我们很容易就能创建系统图标指示器。</p><p>在 Ubuntu/Mint/Debian 上安装：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt-get install gir1.2-appindicator3</span></span></code></pre></div><p>在 Fedora 上安装：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo dnf install libappindicator-gtk3</span></span></code></pre></div><p>对于其他发行版，只需要搜索包含 “appindicator” 的包就行了。</p>',12)),i("p",null,[s[1]||(s[1]=a("在 GNOME Shell 3.26 开始，系统托盘图标被删除了。你需要安装 ",-1)),e(n,{href:"https://extensions.gnome.org/extension/1031/topicons/"},{default:t(()=>[...s[0]||(s[0]=[a("这个扩展",-1)])]),_:1}),s[2]||(s[2]=a("（或者其他扩展）来为桌面启用该功能。否则你无法看到我们创建的指示器。",-1))]),s[19]||(s[19]=o(`<h3 id="基础代码" tabindex="-1">基础代码 <a class="header-anchor" href="#基础代码" aria-label="Permalink to “基础代码”">​</a></h3><p>下面是该指示器的基础代码：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#!/usr/bin/python</span></span>
<span class="line"><span>import os</span></span>
<span class="line"><span>from gi.repository import Gtk as gtk, AppIndicator3 as appindicator</span></span>
<span class="line"><span>def main():</span></span>
<span class="line"><span>  indicator = appindicator.Indicator.new(&quot;customtray&quot;, &quot;semi-starred-symbolic&quot;, appindicator.IndicatorCategory.APPLICATION_STATUS)</span></span>
<span class="line"><span>  indicator.set_status(appindicator.IndicatorStatus.ACTIVE)</span></span>
<span class="line"><span>  indicator.set_menu(menu())</span></span>
<span class="line"><span>  gtk.main()</span></span>
<span class="line"><span>def menu():</span></span>
<span class="line"><span>  menu = gtk.Menu()</span></span>
<span class="line"><span>  </span></span>
<span class="line"><span>  command_one = gtk.MenuItem(&#39;My Notes&#39;)</span></span>
<span class="line"><span>  command_one.connect(&#39;activate&#39;, note)</span></span>
<span class="line"><span>  menu.append(command_one)</span></span>
<span class="line"><span>  exittray = gtk.MenuItem(&#39;Exit Tray&#39;)</span></span>
<span class="line"><span>  exittray.connect(&#39;activate&#39;, quit)</span></span>
<span class="line"><span>  menu.append(exittray)</span></span>
<span class="line"><span>  </span></span>
<span class="line"><span>  menu.show_all()</span></span>
<span class="line"><span>  return menu</span></span>
<span class="line"><span>  </span></span>
<span class="line"><span>def note(_):</span></span>
<span class="line"><span>  os.system(&quot;gedit $HOME/Documents/notes.txt&quot;)</span></span>
<span class="line"><span>def quit(_):</span></span>
<span class="line"><span>  gtk.main_quit()</span></span>
<span class="line"><span>if __name__ == &quot;__main__&quot;:</span></span>
<span class="line"><span>  main()</span></span></code></pre></div><p>我们待会会解释一下代码是怎么工作的。但是现在，让我们将该文本保存为 <code>tray.py</code>，然后使用 Python 运行之：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>python tray.py</span></span></code></pre></div><p>我们会看到指示器运行起来了，如下图所示：</p><p><img src="https://i2.wp.com/fosspost.org/wp-content/uploads/2019/03/Screenshot-at-2019-03-02-1041.png?resize=434%2C140&amp;ssl=1" alt="Create a Custom System Tray Indicator For Your Tasks on Linux 13" title="Create a Custom System Tray Indicator For Your Tasks on Linux 14"></p><p>现在，让我们解释一下这个魔法的原理：</p><ul><li>前三行代码仅仅用来指明 Python 的路径并且导入需要的库。</li><li><code>def main()</code> ：此为指示器的主函数。该函数的代码用来初始化并创建指示器。</li><li><code>indicator = appindicator.Indicator.new(&quot;customtray&quot;，&quot;semi-starred-symbolic&quot;，appindicator.IndicatorCategory.APPLICATION_STATUS)</code> ：这里我们指明创建一个名为 <code>customtray</code> 的新指示器。这是指示器的唯一名称，这样系统就不会与其他运行中的指示器搞混了。同时我们使用名为 <code>semi-starred-symbolic</code> 的图标作为指示器的默认图标。你可以将之改成任何其他值；比如 <code>firefox</code> (如果你希望该指示器使用 FireFox 的图标)，或任何其他你想用的图标名。最后与 <code>APPLICATION_STATUS</code> 相关的部分是指明指示器类别/范围的常规代码。</li><li><code>indicator.set_status(appindicator.IndicatorStatus.ACTIVE)</code>：这一行激活指示器。</li><li><code>indicator.set_menu(menu())</code>：这里说的是我们想使用 <code>menu()</code> 函数（我们会在后面定义) 来为我们的指示器创建菜单项。这很重要，可以让你右击指示器后看到一个可以实施行为的列表。</li><li><code>gtk.main()</code>：运行 GTK 主循环。</li><li>在 <code>menu()</code> 中我们定义了想要指示器提供的行为或项目。<code>command_one = gtk.MenuItem(&#39;My Notes&#39;)</code> 仅仅使用文本 “My notes” 来初始化第一个菜单项，接下来 <code>command_one.connect(&#39;activate&#39;，note)</code> 将菜单的 <code>activate</code> 信号与后面定义的 <code>note()</code> 函数相连接；换句话说，我们告诉我们的系统：“当该菜单项被点击，运行 <code>note()</code> 函数”。最后，<code>menu.append(command_one)</code> 将菜单项添加到列表中。</li><li><code>exittray</code> 相关的行是为了创建一个退出的菜单项，以便让你在想要的时候关闭指示器。</li><li><code>menu.show_all()</code> 以及 <code>return menu</code> 只是返回菜单项给指示器的常规代码。</li><li>在 <code>note(_)</code> 下面是点击 “My Notes” 菜单项时需要执行的代码。这里只是 <code>os.system(&quot;gedit $HOME/Documents/notes.txt&quot;)</code> 这一句话；<code>os.system</code> 函数允许你在 Python 中运行 shell 命令，因此这里我们写了一行命令来使用 <code>gedit</code> 打开家目录下 <code>Documents</code> 目录中名为 <code>notes.txt</code> 的文件。例如，这个可以称为你今后的日常笔记程序了！</li></ul><h3 id="添加你所需要的任务" tabindex="-1">添加你所需要的任务 <a class="header-anchor" href="#添加你所需要的任务" aria-label="Permalink to “添加你所需要的任务”">​</a></h3><p>你只需要修改代码中的两块地方：</p><ol><li>在 <code>menu()</code> 中为你想要的任务定义新的菜单项。</li><li>创建一个新的函数让给该菜单项被点击时执行特定的行为。</li></ol><p>所以，比如说你想要创建一个新菜单项，在点击后，会使用 VLC 播放硬盘中某个特定的视频/音频文件？要做到这一点，只需要在第 17 行处添加下面三行内容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>command_two = gtk.MenuItem(&#39;Play video/audio&#39;)</span></span>
<span class="line"><span>command_two.connect(&#39;activate&#39;, play)</span></span>
<span class="line"><span>menu.append(command_two)</span></span></code></pre></div><p>然后在第 30 行添加下面内容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>def play(_):</span></span>
<span class="line"><span>  os.system(&quot;vlc /home/&lt;username&gt;/Videos/somevideo.mp4&quot;)</span></span></code></pre></div><p>将 <code>/home/&lt;username&gt;/Videos/somevideo.mp4</code> 替换成你想要播放的视频/音频文件路径。现在保存该文件然后再次运行该指示器：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>python tray.py</span></span></code></pre></div><p>你将会看到：</p><p><img src="https://i2.wp.com/fosspost.org/wp-content/uploads/2019/03/Screenshot-at-2019-03-02-1141.png?resize=440%2C149&amp;ssl=1" alt="Create a Custom System Tray Indicator For Your Tasks on Linux 15" title="Create a Custom System Tray Indicator For Your Tasks on Linux 16"></p><p>而且当你点击新创建的菜单项时，VLC 会开始播放！</p><p>要创建其他项目/任务，只需要重复上面步骤即可。但是要小心，需要用其他命令来替换 <code>command_two</code>，比如 <code>command_three</code>，这样在变量之间才不会产生冲突。然后定义新函数，就像 <code>play(_)</code> 函数那样。</p><p>可能性是无穷的；比如我用这种方法来从网上获取数据（使用 urllib2 库）并显示出来。我也用它来在后台使用 <code>mpg123</code> 命令播放 mp3 文件，而且我还定义了另一个菜单项来 <code>killall mpg123</code> 以随时停止播放音频。比如 Steam 上的 CS:GO 退出很费时间（窗口并不会自动关闭），因此，作为一个变通的方法，我只是最小化窗口然后点击某个自建的菜单项，它会执行 <code>killall -9 csgo_linux64</code> 命令。</p><p>你可以使用这个指示器来做任何事情：升级系统包、运行其他脚本——字面上的任何事情。</p><h3 id="自动启动" tabindex="-1">自动启动 <a class="header-anchor" href="#自动启动" aria-label="Permalink to “自动启动”">​</a></h3><p>我们希望系统托盘指示器能在系统启动后自动启动，而不用每次都手工运行。要做到这一点，只需要在自启动应用程序中添加下面命令即可（但是你需要将 <code>tray.py</code> 的路径替换成你自己的路径）:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>nohup python /home/&lt;username&gt;/tray.py &amp;</span></span></code></pre></div><p>下次重启系统，指示器会在系统启动后自动开始工作了！</p><h3 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to “结论”">​</a></h3><p>你现在知道了如何为你想要的任务创建自己的系统托盘指示器了。根据每天需要运行的任务的性质和数量，此方法可以节省大量时间。有些人偏爱从命令行创建别名，但是这需要你每次都打开终端窗口或者需要有一个可用的下拉式终端仿真器，而这里，这个系统托盘指示器一直在工作，随时可用。</p><p>你以前用过这个方法来运行你的任务吗？很想听听你的想法。</p><hr>`,32)),i("p",null,[s[4]||(s[4]=a("via: ",-1)),e(n,{href:"https://fosspost.org/tutorials/custom-system-tray-icon-indicator-linux"},{default:t(()=>[...s[3]||(s[3]=[a("https://fosspost.org/tutorials/custom-system-tray-icon-indicator-linux",-1)])]),_:1})]),i("p",null,[s[9]||(s[9]=a("作者：",-1)),e(n,{href:"https://fosspost.org/author/mhsabbagh"},{default:t(()=>[...s[5]||(s[5]=[a("M.Hanny Sabbagh",-1)])]),_:1}),s[10]||(s[10]=a(" 选题：",-1)),e(n,{href:"https://github.com/lujun9972"},{default:t(()=>[...s[6]||(s[6]=[a("lujun9972",-1)])]),_:1}),s[11]||(s[11]=a(" 译者：",-1)),e(n,{href:"https://github.com/lujun9972"},{default:t(()=>[...s[7]||(s[7]=[a("lujun9972",-1)])]),_:1}),s[12]||(s[12]=a(" 校对：",-1)),e(n,{href:"https://github.com/wxy"},{default:t(()=>[...s[8]||(s[8]=[a("wxy",-1)])]),_:1})]),i("p",null,[s[15]||(s[15]=a("本文由 ",-1)),e(n,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[13]||(s[13]=[a("LCTT",-1)])]),_:1}),s[16]||(s[16]=a(" 原创编译，",-1)),e(n,{href:"https://linux.cn/"},{default:t(()=>[...s[14]||(s[14]=[a("Linux中国",-1)])]),_:1}),s[17]||(s[17]=a(" 荣誉推出",-1))])])}const x=p(c,[["render",u]]);export{C as __pageData,x as default};
